/** Retire only an open second-meeting prompt whose unresolved action advanced or completed. */
export function supersededSecondMeetingPrompts(history:MeetingCandidate[],openPromptIds:string[],opportunity:CoachOpportunity){
 const open=new Set(openPromptIds);return history.flatMap(candidate=>{if(!candidate.promptId||!open.has(candidate.promptId))return[];const priorStep=meetingClosePromptStep(candidate),isClose=candidate.branch==='follow_up'&&(/second (?:meeting|conversation)/i.test(`${candidate.goal||''} ${candidate.wording||candidate.text}`)||priorStep!==null);if(!isClose)return[];return opportunity.secondMeetingAchieved||opportunity.callGoal==='secure_second_meeting'&&!!priorStep&&!!opportunity.secondMeetingCloseStep&&priorStep!==opportunity.secondMeetingCloseStep?[candidate.promptId]:[];});
}

const priorityRank:Record<NonNullable<MeetingCandidate['priority']>,number>={low:0,normal:1,high:2,critical:3};
function priorityOf(candidate:MeetingCandidate|null){return candidate?.priority||'normal';}
export function coachingDiagnostics(trace:CoachTrace[]){
 const visible=trace.filter(e=>e.stage==='prompt_visible'),opportunities=trace.filter(e=>e.stage==='opportunity_detected'),high=opportunities.filter(e=>e.priority==='high'||e.priority==='critical');
 const highSequences=new Set(high.map(e=>e.sequence)),visibleHigh=new Set(visible.filter(e=>highSequences.has(e.sequence)).map(e=>e.sequence));
 const latencies=visible.filter(e=>highSequences.has(e.sequence)).flatMap(e=>{const detected=opportunities.find(o=>o.sequence===e.sequence);return detected?[Math.max(0,e.at-detected.at)]:[];}).sort((a,b)=>a-b),middle=Math.floor(latencies.length/2),medianMs=latencies.length?(latencies.length%2?latencies[middle]:(latencies[middle-1]+latencies[middle])/2):null;
 const missed=high.filter(e=>!visibleHigh.has(e.sequence)).map(e=>({sequence:e.sequence,causes:Array.from(new Set(trace.filter(item=>item.sequence===e.sequence&&['generation_failed','prompt_suppressed','prompt_expired','prompt_queued','no_prompt_generated'].includes(item.stage)).map(item=>item.reason||item.stage)))}));
 const critical=opportunities.filter(e=>e.priority==='critical'),criticalLatencies=visible.flatMap(e=>{const detected=critical.find(o=>o.sequence===e.sequence);return detected?[Math.max(0,e.at-detected.at)]:[];});
 const silenceEvents=trace.filter(e=>e.stage==='silence_recheck_detected'),silenceLatencies=silenceEvents.flatMap(event=>{const shown=visible.find(item=>item.sequence===event.sequence);return shown?[Math.max(0,shown.at-event.at)]:[];}).sort((a,b)=>a-b),silenceMiddle=Math.floor(silenceLatencies.length/2),medianSilenceMs=silenceLatencies.length?(silenceLatencies.length%2?silenceLatencies[silenceMiddle]:(silenceLatencies[silenceMiddle-1]+silenceLatencies[silenceMiddle])/2):null;
 return {opportunitiesDetected:opportunities.length,promptsGenerated:trace.filter(e=>e.stage==='prompt_generated').length,generationFailures:trace.filter(e=>e.stage==='generation_failed').length,promptsSuppressed:trace.filter(e=>e.stage==='prompt_suppressed').length,promptsSuppressedMissedWindow:trace.filter(e=>e.stage==='prompt_suppressed'&&e.reason==='missed_window').length,promptsQueued:trace.filter(e=>e.stage==='prompt_queued').length,promptsVisible:visible.length,visibleDurationMs:trace.filter(e=>e.stage==='prompt_visibility_ended').reduce((n,e)=>n+(e.durationMs||0),0),promptsReplaced:trace.filter(e=>e.stage==='prompt_replaced').length,promptsExpired:trace.filter(e=>e.stage==='prompt_expired').length,promptsMissedAtEnd:trace.filter(e=>e.stage==='prompt_expired'&&e.reason==='meeting_ended').length,highPriorityOpportunities:high.length,highPriorityVisible:visibleHigh.size,medianHighPriorityDetectionToVisibleMs:medianMs,worstCriticalDetectionToVisibleMs:criticalLatencies.length?Math.max(...criticalLatencies):null,silenceRechecks:silenceEvents.length,medianSilenceDetectionToVisibleMs:medianSilenceMs,worstSilenceDetectionToVisibleMs:silenceLatencies.length?Math.max(...silenceLatencies):null,highPriorityMissCount:missed.length,highPriorityMissReasons:missed};
}

export function inspectLiveCoaching(raw:unknown,segments:MeetingSegment[],facts:MeetingFact[],history:MeetingCandidate[],sequence:number,at=Date.now(),opportunity?:CoachOpportunity){
 const value=raw&&typeof raw==='object'?raw as Record<string,unknown>:{},trace:CoachTrace[]=[],candidates:MeetingCandidate[]=[];
 const list=Array.isArray(value.questions)?value.questions.slice(0,6):[];
 for(const [index,item] of list.entries()){
  const promptId=`${sequence}:q${index}`;let effectivePromptId=promptId,replacedFormat=false;
  trace.push({stage:'prompt_generated',at,sequence,promptId,priority:opportunity?.priority||'normal'});
  let candidate:MeetingCandidate|undefined=groundedCoachingList([item],segments,facts,1)[0];
  const unsupportedFormat=!!candidate&&unsupportedProductFormat(candidate,facts);
  if(unsupportedFormat){
   replacedFormat=true;
   trace.push({stage:'prompt_suppressed',at,sequence,promptId,reason:'unsupported_product_format_assumption'});
   const source=segments.filter(s=>!s.gap&&s.text.trim()).at(-1);
   if(source){
    const wording=/explor|looking into|having a look/i.test(source.text)?'When you say you’re exploring this, are you thinking about a workshop, a pilot, ongoing access, or are you not that far along yet?':'What sort of approach, if any, are you considering at this stage?';
    candidate={text:wording,wording,lead:'The format is not established in the supplied context. Clarify before framing a solution.',goal:'Clarify the format before discussing a solution.',quote:source.text.trim().slice(0,600),segmentId:source.id,evidenceKind:'transcript',angle:'criteria'};
    effectivePromptId=`${sequence}:format${index}`;
    trace.push({stage:'prompt_generated',at,sequence,promptId:effectivePromptId,priority:opportunity?.priority||'normal',reason:'format_clarification_fallback'});
   }else candidate=undefined;
  }
  const row=item&&typeof item==='object'?item as Record<string,unknown>:null;
  const allowedBranches=new Set(['consequence','priority','trigger','stakeholder','criteria','workaround','funding','operational_impact','personal_impact','next_step','graceful_exit','follow_up']),branch=replacedFormat?'criteria':allowedBranches.has(String(row?.branch))?row?.branch as MeetingCandidate['branch']:opportunity?.branch,priority=opportunity?.priority||candidate?.priority||'normal',enriched=candidate?{...candidate,branch,priority}:null;
  const source= row&&typeof row.segmentId==='string'?(row.evidenceKind==='recorded'?facts.find(f=>f.id===row.segmentId)?.text:segments.find(s=>s.id===row.segmentId&&!s.gap)?.text):undefined;
  const reason=!candidate?(!row||typeof row.text!=='string'||!row.text.trim()?'malformed_candidate':!source?'unknown_or_gap_source':typeof row.quote!=='string'||row.quote.trim().length<8||!source.includes(row.quote)?'quote_not_in_source':'invalid_candidate'):problemDiscoveryProbe(candidate,row)&&!segments.some(segment=>!segment.gap&&groundedProblemText(segment.text))?'ungrounded_problem_probe':typeof candidate.goal!=='string'||!candidate.goal.trim()||candidate.goal.length>120?'missing_call_goal':(!candidate.wording&&!candidate.text.includes('?')||/^(?:try|explore|choose|change|shift|switch|move).{0,32}(?:direction|branch|topic|something else)[.!]?$/i.test(candidate.wording||candidate.text))?'missing_usable_wording':coachingSuppression(enriched!,[...history,...candidates]);
  if(reason){trace.push({stage:'prompt_suppressed',at,sequence,promptId,reason});continue;}
  if(candidates.length>=2){trace.push({stage:'prompt_suppressed',at,sequence,promptId,reason:'display_capacity'});continue;}
  candidates.push({...enriched!,promptId:effectivePromptId});
 }
 if(!list.length)trace.push({stage:'no_prompt_generated',at,sequence,reason:'model_abstained'});
 const resolved=Array.isArray(value.resolvedSuggestions)?value.resolvedSuggestions:[];
 const resolvedPrompts=resolved.flatMap(r=>r&&typeof r.promptId==='string'&&history.some(h=>h.promptId===r.promptId)&&typeof r.quote==='string'&&r.quote.length>=8&&segments.slice(-6).some(s=>!s.gap&&s.id===r.segmentId&&s.text.includes(r.quote))?[r.promptId]:[]);
 return {candidates,trace,resolvedPrompts};
}

export type CoachRuntime={current:MeetingCandidate|null;pending:MeetingCandidate|null;shownAt:number;queuedAt:number;visiblePromptId:string|null;visibleAt:number;history:MeetingCandidate[];trace:CoachTrace[]};
export const createCoachRuntime=():CoachRuntime=>({current:null,pending:null,shownAt:0,queuedAt:0,visiblePromptId:null,visibleAt:0,history:[],trace:[]});
const EXPIRE_MS=40000,QUEUE_MS=24000;
function note(s:CoachRuntime,stage:string,at:number,c:MeetingCandidate|null,reason?:string,durationMs?:number){s.trace=[...s.trace,{stage,at,sequence:Number(c?.promptId?.split(':')[0]??-1),promptId:c?.promptId,reason,priority:c?.priority||'normal',durationMs}].slice(-1200);}
function endVisibility(s:CoachRuntime,at:number,c:MeetingCandidate,reason:string){if(s.visiblePromptId===c.promptId){note(s,'prompt_visibility_ended',at,c,reason,Math.max(0,at-s.visibleAt));s.visiblePromptId=null;s.visibleAt=0;}}
function show(s:CoachRuntime,c:MeetingCandidate,at:number){if(s.current){endVisibility(s,at,s.current,'replaced');note(s,'prompt_replaced',at,s.current,'new_relevant_prompt');}s.current=c;s.shownAt=at;note(s,'prompt_selected',at,c);}
function sameUnresolvedCloseStep(state:CoachRuntime,candidate:MeetingCandidate){
 const step=meetingClosePromptStep(candidate);if(candidate.branch!=='follow_up'||!step)return false;
 const latest=[...state.trace].reverse().find(event=>event.stage==='opportunity_detected'&&event.callGoal==='secure_second_meeting');
 return !!latest&&latest.secondMeetingCloseStep===step&&latest.secondMeetingAchieved!==true;
}
export function advanceCoach(state:CoachRuntime,at:number):CoachRuntime{
 const s={...state};
 if(s.pending&&priorityRank[priorityOf(s.pending)]<2&&at-s.queuedAt>=QUEUE_MS){note(s,'prompt_expired',at,s.pending,'queue_age');s.pending=null;}
 if(s.current&&priorityRank[priorityOf(s.current)]<2&&at-s.shownAt>=EXPIRE_MS){endVisibility(s,at,s.current,'expired');note(s,'prompt_expired',at,s.current,'display_age');s.current=null;}
 if(s.pending&&!s.current){const c=s.pending;s.pending=null;show(s,c,at);}
 return s.current===state.current&&s.pending===state.pending?state:s;
}
export function receiveCoach(state:CoachRuntime,candidates:MeetingCandidate[],trace:CoachTrace[],at:number,resolved:string[]=[],closed=false,latestCapturedSequence?:number):CoachRuntime{
 const initial={...state,trace:[...state.trace,...trace].slice(-1200)};
 for(const key of ['current','pending'] as const)if(initial[key]&&(closed||resolved.includes(initial[key]!.promptId||''))){if(key==='current')endVisibility(initial,at,initial[key]!,closed?'meeting_ended':'answered_or_moved_on');note(initial,'prompt_expired',at,initial[key],closed?'meeting_ended':'answered_or_moved_on');initial[key]=null;}
 const s={...advanceCoach(initial,at)};
 for(const [i,candidate] of candidates.slice(0,2).entries()){
  const detectedSequence=trace.find(event=>event.stage==='opportunity_detected')?.sequence??candidate.detectedSequence;
  const c={...candidate,...(typeof detectedSequence==='number'?{detectedSequence}:{}),promptId:candidate.promptId||`${candidate.segmentId}:q${i}`};
 if(priorityRank[priorityOf(c)]>=2&&latestCapturedSequence!==undefined&&typeof c.detectedSequence==='number'&&latestCapturedSequence-c.detectedSequence>0&&!sameUnresolvedCloseStep(s,c)){note(s,'prompt_suppressed',at,c,'missed_window');continue;}
  if(priorityOf(c)==='critical'&&s.pending&&priorityRank[priorityOf(s.pending)]<priorityRank.critical){note(s,'prompt_suppressed',at,s.pending,'preempted_by_critical');s.pending=null;}
  const reason=closed?'meeting_ended':coachingSuppression(c,[...s.history,...(s.current?[s.current]:[]),...(s.pending?[s.pending]:[])]);
  if(reason){note(s,'prompt_suppressed',at,c,reason);continue;}
  note(s,'prompt_queued',at,c);
  const currentRank=priorityRank[priorityOf(s.current)],nextRank=priorityRank[priorityOf(c)];
  // A newly grounded critical close step with fresh evidence should replace
  // outdated advice even when its broad branch and goal are unchanged. The
  // semantic suppression check above has already rejected same-evidence repeats.
  const newerDistinctHigh=!!s.current&&nextRank>=2&&nextRank===currentRank&&(candidate.branch!==s.current.branch||candidate.goal!==s.current.goal||candidate.segmentId!==s.current.segmentId||candidate.detectedSequence!==s.current.detectedSequence);
  if(!s.current||(nextRank>=2&&(nextRank>currentRank||newerDistinctHigh)))show(s,c,at);
  else{if(s.pending)note(s,'prompt_suppressed',at,s.pending,'superseded_while_queued');s.pending=c;s.queuedAt=at;}
 }
 return s;
}

/** UI calls this after its render commit; selection/queueing alone is not a display. */
export function markCoachRenderAttempted(state:CoachRuntime,promptId:string,at:number,latestCapturedSequence?:number):CoachRuntime{const current=state.current;if(!current||current.promptId!==promptId)return state;const s={...state};if(s.trace.some(e=>e.stage==='prompt_render_attempted'&&e.promptId===promptId))return s;if(priorityRank[priorityOf(current)]>=2&&latestCapturedSequence!==undefined&&typeof current.detectedSequence==='number'&&latestCapturedSequence-current.detectedSequence>0&&!sameUnresolvedCloseStep(s,current)){note(s,'prompt_suppressed',at,current,'missed_window');s.current=null;s.pending=null;s.visiblePromptId=null;s.visibleAt=0;return s;}note(s,'prompt_render_attempted',at,current);return s;}
export function markCoachDisplayed(state:CoachRuntime,promptId:string,at:number,latestCapturedSequence?:number):CoachRuntime{
 const current=state.current;if(!current||current.promptId!==promptId)return state;const s={...state};
 if(priorityRank[priorityOf(current)]>=2&&latestCapturedSequence!==undefined&&typeof current.detectedSequence==='number'&&latestCapturedSequence-current.detectedSequence>0&&!sameUnresolvedCloseStep(s,current)){note(s,'prompt_suppressed',at,current,'missed_window');s.current=null;s.pending=null;s.visiblePromptId=null;s.visibleAt=0;return s;}
 if(s.visiblePromptId!==promptId){if(s.visiblePromptId&&s.current)endVisibility(s,at,current,'out_of_view');s.visiblePromptId=promptId;s.visibleAt=at;note(s,'prompt_visible',at,current);}
 if(s.trace.some(e=>e.stage==='prompt_displayed'&&e.promptId===promptId))return s;
 s.shownAt=at;s.history=[...s.history,current].slice(-200);note(s,'prompt_displayed',at,current);return s;
}
export function markCoachNotVisible(state:CoachRuntime,promptId:string,at:number):CoachRuntime{if(state.visiblePromptId!==promptId||state.current?.promptId!==promptId)return state;const s={...state};endVisibility(s,at,s.current!,'out_of_view');return s;}
